/** Fetch-based SSE connection with Authorization header (BATCH-31, HB-01).
 *  Replaces the legacy sseUrl() which put API keys in query params.
 */
export function sseFetch(
  path: string,
  callbacks: {
    onEvent: (data: string) => void;
    onOpen?: () => void;
    onError?: (error: Error) => void;
  },
): AbortController {
  const controller = new AbortController();
  const headers: Record<string, string> = {};
  const key = getApiKey();
  if (key) {
    headers["X-API-Key"] = key;
  }
  const base = getBaseUrl() || window.location.origin;
  const url = `${base}${API_PREFIX}${path}`;

  (async () => {
    try {
      const response = await fetch(url, { headers, signal: controller.signal });
      if (!response.ok) {
        throw new Error(`SSE connection failed: HTTP ${response.status}`);
      }
      callbacks.onOpen?.();
      const reader = response.body!.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        // SSE events are separated by blank lines (\n\n)
        const parts = buffer.split("\n\n");
        buffer = parts.pop() || "";
        for (const part of parts) {
          for (const line of part.split("\n")) {
            if (line.startsWith("data: ")) {
              callbacks.onEvent(line.slice(6));
            }
          }
        }
      }
    } catch (err) {
      if ((err as Error).name !== "AbortError" && callbacks.onError) {
        callbacks.onError(err instanceof Error ? err : new Error(String(err)));
      }
    }
  })();

  return controller;
}

"""Sandbox manager — auto-detection, backend coordination, and convenience API.

Central point of access for sandboxed execution. Auto-detects the strongest
available backend (Docker > Subprocess > Noop) or allows explicit selection.
"""

from __future__ import annotations

import logging
from typing import Any

from backend.pipeline.sandboxing.docker_backend import DockerSandboxBackend
from backend.pipeline.sandboxing.noop_backend import NoopSandboxBackend
from backend.pipeline.sandboxing.protocol import (
    ExecutionResult,
    SandboxBackend,
    SandboxConfig,
    SandboxSession,
)
from backend.pipeline.sandboxing.subprocess_backend import SubprocessSandboxBackend

logger = logging.getLogger(__name__)

_BACKEND_ORDER: list[str] = ["docker", "subprocess", "noop"]


class SandboxManager:
    """Central coordinator for sandbox backends."""

    def __init__(
        self,
        backend_name: str = "auto",
        default_config: SandboxConfig | None = None,
        shell_image: str = "alpine:3.19",
        python_image: str = "python:3.11-slim",
    ) -> None:
        self._backend_name = backend_name
        self._default_config = default_config or SandboxConfig()
        self._shell_image = shell_image
        self._python_image = python_image
        self._backends: dict[str, SandboxBackend] = {}
        self._active: SandboxBackend | None = None

        self._init_backends()

    def _init_backends(self) -> None:
        """Pre-register all backend instances."""
        self._backends["noop"] = NoopSandboxBackend(self._default_config)
        self._backends["subprocess"] = SubprocessSandboxBackend(self._default_config)
        self._backends["docker"] = DockerSandboxBackend(
            self._default_config,
            shell_image=self._shell_image,
            python_image=self._python_image,
        )

    def detect_backend(self) -> SandboxBackend:
        """Auto-detect the strongest available backend."""
        if self._backend_name != "auto":
            backend = self._backends.get(self._backend_name)
            if backend is None:
                logger.warning("Unknown backend %r, falling back to noop", self._backend_name)
                return self._backends["noop"]
            if not backend.is_available():
                logger.warning(
                    "Requested backend %r not available, falling back to noop",
                    self._backend_name,
                )
                return self._backends["noop"]
            return backend

        for name in _BACKEND_ORDER:
            backend = self._backends[name]
            if backend.is_available():
                logger.info("Auto-detected sandbox backend: %s", name)
                return backend

        # Should never reach here since noop is always available
        return self._backends["noop"]

    @property
    def active_backend(self) -> SandboxBackend:
        """Lazily resolve and cache the active backend."""
        if self._active is None:
            self._active = self.detect_backend()
        return self._active

    @property
    def backend_name(self) -> str:
        return self.active_backend.name

    async def execute_shell(
        self, command: str, config: SandboxConfig | None = None
    ) -> ExecutionResult:
        """Execute a shell command in the sandbox."""
        return await self.active_backend.execute_shell(command, config)

    async def execute_python(
        self, code: str, config: SandboxConfig | None = None
    ) -> ExecutionResult:
        """Execute Python code in the sandbox."""
        return await self.active_backend.execute_python(code, config)

    def create_session(self, config: SandboxConfig | None = None) -> SandboxSession:
        """Create a persistent sandbox session."""
        backend = self.active_backend
        if not hasattr(backend, "create_session"):
            raise RuntimeError(
                f"Backend {backend.name!r} does not support persistent sessions"
            )
        return backend.create_session(config or self._default_config)  # type: ignore[union-attr]

    def get_backend(self, name: str) -> SandboxBackend | None:
        """Get a specific backend by name."""
        return self._backends.get(name)

    def list_backends(self) -> dict[str, bool]:
        """List all registered backends and their availability."""
        return {name: b.is_available() for name, b in self._backends.items()}


# Module-level singleton
_manager: SandboxManager | None = None


def get_sandbox_manager() -> SandboxManager:
    global _manager
    if _manager is None:
        _manager = SandboxManager()
    return _manager


def reset_sandbox_manager() -> None:
    """Reset the singleton — mainly for testing."""
    global _manager
    _manager = None

"""API error hierarchy for proper HTTP status codes.

Standardized error format:
    {"error": {"code": "...", "message": "...", "hint": "..."}}

All errors include a status_code, error code string, human-readable message,
and optional remediation hint. The unified error handler in app.py serializes
these into a consistent JSON response with an X-Request-Id header.
"""

from __future__ import annotations


class APIError(Exception):
    """Base API error with HTTP status code, error code, message, and hint.

    Attributes:
        status_code: HTTP status code (e.g. 400, 404, 500).
        code: Machine-readable error code string (e.g. "NOT_FOUND").
        message: Human-readable error description.
        hint: Optional remediation hint for the client.
    """

    def __init__(
        self,
        status_code: int,
        detail: str,
        code: str | None = None,
        hint: str | None = None,
    ):
        self.status_code = status_code
        self.code = code or _status_to_code(status_code)
        self.message = detail
        self.hint = hint
        super().__init__(detail)

    def to_dict(self) -> dict:
        """Serialize to the standardized error format."""
        payload: dict = {
            "code": self.code,
            "message": self.message,
        }
        if self.hint:
            payload["hint"] = self.hint
        return {"error": payload}


class BadRequestError(APIError):
    """400 Bad Request."""

    def __init__(self, detail: str = "Bad request", hint: str | None = None):
        super().__init__(status_code=400, detail=detail, code="BAD_REQUEST", hint=hint)


class UnauthorizedError(APIError):
    """401 Unauthorized."""

    def __init__(self, detail: str = "Invalid or missing API key", hint: str | None = None):
        default_hint = "Provide a valid API key via the X-API-Key header"
        super().__init__(
            status_code=401,
            detail=detail,
            code="UNAUTHORIZED",
            hint=hint or default_hint,
        )


class ForbiddenError(APIError):
    """403 Forbidden."""

    def __init__(self, detail: str = "Forbidden", hint: str | None = None):
        super().__init__(status_code=403, detail=detail, code="FORBIDDEN", hint=hint)


class ConflictError(APIError):
    """409 Conflict."""

    def __init__(self, detail: str = "Conflict", hint: str | None = None):
        super().__init__(status_code=409, detail=detail, code="CONFLICT", hint=hint)


class NotFoundError(APIError):
    """404 Not Found."""

    def __init__(self, detail: str = "Resource not found", hint: str | None = None):
        super().__init__(status_code=404, detail=detail, code="NOT_FOUND", hint=hint)


class UnprocessableEntityError(APIError):
    """422 Unprocessable Entity."""

    def __init__(self, detail: str = "Validation error", hint: str | None = None):
        super().__init__(
            status_code=422, detail=detail, code="UNPROCESSABLE_ENTITY", hint=hint
        )


class ServiceUnavailableError(APIError):
    """503 Service Unavailable."""

    def __init__(self, detail: str = "Service unavailable", hint: str | None = None):
        super().__init__(
            status_code=503, detail=detail, code="SERVICE_UNAVAILABLE", hint=hint
        )


class ProviderConfigurationError(APIError):
    """500 Provider configuration error — replaces SystemExit in provider_factory."""

    def __init__(self, detail: str, hint: str | None = None):
        super().__init__(
            status_code=500, detail=detail, code="PROVIDER_CONFIG_ERROR", hint=hint
        )


def _status_to_code(status_code: int) -> str:
    """Convert an HTTP status code to a default error code string."""
    _MAP = {
        400: "BAD_REQUEST",
        401: "UNAUTHORIZED",
        403: "FORBIDDEN",
        404: "NOT_FOUND",
        405: "METHOD_NOT_ALLOWED",
        409: "CONFLICT",
        422: "UNPROCESSABLE_ENTITY",
        429: "RATE_LIMITED",
        500: "INTERNAL_ERROR",
        503: "SERVICE_UNAVAILABLE",
    }
    return _MAP.get(status_code, f"ERROR_{status_code}")

